let p26=null;
const beforeProgram26=render;
render=function(){if(location.hash!=='#program/26')return beforeProgram26();document.getElementById('app').innerHTML=integratedShell('program26',heading('Agentic AI Systems Design','Loading the ten-week design…'),model.role);bind();fetch('data/program26-design.json').then(r=>{if(!r.ok)throw Error('Design unavailable');return r.json();}).then(d=>{if(location.hash!=='#program/26')return;p26=d;document.getElementById('app').innerHTML=integratedShell('program26',heading(d.title,'Scholarion Academy · Advanced Builder · Ten-week draft')+`<section class="card prose" id="p26-brochure"><p><a href="#catalog">Catalog previews</a> · <a href="#pathways">Learning pathways</a> · <a href="#program-studio">Instructor design studio</a></p><p>Lead faculty: ${esc(d.faculty)}. Facilitators are not yet confirmed.</p><p>Proposed live online experience. Cohort dates, seats, fee and registration deadline are unconfigured. Recordings, office hours and live support are not yet connected.</p><button class="button" disabled>Applications unavailable</button> <button class="button secondary" id="p26-download">Download draft brochure</button><h2>Measurable competencies</h2><ul>${d.competencies.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ul><h2>Weekly design and activities</h2><p>${esc(d.schedule)}</p>${d.modules.map(m=>`<details><summary>Week ${m.week}: ${esc(m.title)}</summary><p>${esc(m.outcomes[0].text)}</p><h3>Student activity</h3><p>${esc(m.activity.student)}</p><h3>Instructor review guidance</h3><p>${esc(m.activity.instructor)}</p></details>`).join('')}<h2>Twelve core lab briefs</h2>${d.labs.map(l=>`<details><summary>${esc(l.id)} · ${esc(l.title)}</summary><p>Week ${l.week} · ${l.minutes} minutes proposed</p><p>${esc(l.brief)}</p><p>${esc(l.data)}</p><p>${esc(l.status)}</p></details>`).join('')}<h2>Research design memo</h2><p>${esc(d.researchMemo)}</p><h2>Capstone and defense</h2><p>${esc(d.capstone)}</p><ul>${d.rubric.map(r=>`<li>${esc(r.criterion)}: ${r.points} points</li>`).join('')}</ul><p>Pass/no-pass design: twelve lab checkpoints, six quizzes at 70% or above, research memo, capstone and final presentation. The capstone pass threshold is not configured, so eligibility and issuance remain blocked.</p><h2>Optional stretch exercises</h2><ul>${d.stretch.map(s=>`<li>${esc(s.title)}</li>`).join('')}</ul><h2>Certificate and funding</h2><p>Proposed Scholarion Academy Certificate of Completion — non-credit professional training, plus an Agentic Systems Design badge. Digital issuance in legal name and public verification are not connected. Issue timing and content-access period are unconfigured.</p><p>${esc(d.funding)}</p><h2>Transfer</h2><ul>${d.transfer.map(t=>`<li>#${t.to}: ${esc(t.mapping)}. Proposed only; no approved waiver.</li>`).join('')}</ul><h2>Publication gates</h2><ul>${d.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><h2>FAQ and support</h2><p>Python, algorithms, data structures and basic LLM concepts are expected. No framework or vendor affiliation is implied. Tool versions and research citations remain under review.</p><p>Refunds, deferrals, late-entry extensions, accessibility contacts and payment methods require approved configuration. Do not rely on a promised access period or certificate issue date.</p><a href="#help">Local support and team inquiry</a> · <a href="#assessment">Assessment setup guidance</a></section><section class="card prose"><h2>Prerequisite self-check</h2><p>Advisory self-report only; not an admission test or enrollment approval.</p><form id="p26-check">${[['python','Can you write and test Python functions?'],['structures','Can you use lists, dictionaries and basic algorithms?'],['apis','Can you validate an API response and handle an error?'],['llm','Can you explain LLM limitations and context?']].map(([k,q])=>`<label style="display:block;margin:12px 0">${esc(q)}<select name="${k}" required><option value="">Choose</option><option value="yes">Yes</option><option value="no">Not yet</option></select></label>`).join('')}<button class="button">Show preparation route</button></form><p id="p26-result" role="status"></p></section>`,model.role);bind();normalizeWorkspace();document.title=d.title+' · Scholarion Academy';}).catch(e=>{document.getElementById('app').textContent=e.message;});};
document.addEventListener('submit',e=>{if(e.target.id!=='p26-check')return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target));const target=v.python!=='yes'||v.structures!=='yes'?16:v.apis!=='yes'||v.llm!=='yes'?19:26;document.getElementById('p26-result').innerHTML=target===26?'Your self-report suggests readiness to discuss #26 with faculty. Enrollment is not approved.':`Review <a href="#program/${target}">program #${target}</a>${target===19?' followed by #16':''} before faculty review for #26. This is preparation guidance, not a required paid purchase.`;});
document.addEventListener('click',e=>{if(e.target.id!=='p26-download'||!p26)return;download('scholarion-program-26-draft-brochure.html','<!doctype html><html lang="en"><meta charset="utf-8"><title>Program 26 — Draft brochure</title><body><h1>'+esc(p26.title)+'</h1><p>Draft for academic review. Not open for enrollment.</p>'+document.getElementById('p26-brochure').innerHTML.replace(/<button[\s\S]*?<\/button>/g,'')+'</body></html>','text/html');});
render();
